import re
def plain(h): return re.sub(r'<[^>]*>','',h).replace('&amp;','&').replace('&lt;','<').replace('&gt;','>')
meta=[{"t":c["t"],"l":1,"n":sum(len(plain(b)) for b in c["b"])} for c in ch]
chars=sum(m["n"] for m in meta)
print(json.dumps({"chars":chars,"chapters":meta},ensure_ascii=False))
